type StopInput = Partial<GuideStop> & {
  id: string;
  poiId: string;
  name: string;
  coordinates: [number, number];
  description: string;
  sourcePhoto: string;
  officialUrl: string;
  mapQuery?: string;
  editorialUrls?: string[];
  platformUrls?: string[];
};

function stop(input: StopInput): GuideStop {
  const {
    id,
    poiId,
    name,
    coordinates,
    description,
    sourcePhoto,
    officialUrl,
    mapQuery,
    editorialUrls = [],
    platformUrls = [],
    sourceEvidence,
    bookingUrl,
    sourceUrls: extraSourceUrls = [],
    ...rest
  } = input;
  const mapUrl = sourceEvidence?.mapUrl ?? maps(mapQuery ?? `${name} Dubai`);
  const sourceUrls = [officialUrl, mapUrl, sourcePhoto, ...editorialUrls, ...platformUrls, ...extraSourceUrls];

  return {
    id,
    poiId,
    name,
    coordinates,
    description,
    photo: sourcePhoto,
    imageSourceUrl: sourcePhoto,
    imageSourceName: sourcePhoto.includes("wikimedia.org") ? "Wikimedia Commons" : "Official/property media",
    sourceUrls: [...new Set(sourceUrls)],
    sourceEvidence: {
      officialUrl,
      mapUrl,
      currentStatusUrl: officialUrl,
      imageSourceUrl: sourcePhoto,
      editorialUrls,
      platformUrls,
      checkedAt,
      notes: "Official schedule, current map listing, and active status checked on the research date.",
      ...sourceEvidence,
    },
    officialUrl,
    ...(bookingUrl ? { bookingUrl } : {}),
    ...rest,
  };
}

