function listSources(overview: ListSource[], stops: GuideStop[]): ListSource[] {
  const candidates = [
    ...overview,
    ...stops.flatMap((item) => [
      item.officialUrl ? source(`${item.name} official/property page`, item.officialUrl) : undefined,
      item.sourceEvidence?.mapUrl ? source(`${item.name} current map listing`, item.sourceEvidence.mapUrl) : undefined,
    ]),
  ].filter(Boolean) as ListSource[];
  const seen = new Set<string>();
  return candidates.filter((item) => {
    if (seen.has(item.url)) return false;
    seen.add(item.url);
    return true;
  });
}

function guide(
  category: ListCategory,
  id: string,
  slug: string,
  seoSlug: string,
  title: string,
  description: string,
  stops: GuideStop[],
  overviewSources: ListSource[],
  seoTitle: string,
  seoDescription: string,
): MapList {
  return {
    id,
    slug,
    seoSlug,
    seoTitle,
    seoDescription,
    title,
    description,
    photo: stops[0]?.photo,
    url: maps(`${title} Dubai`),
    category,
    location: dubaiLocation,
    creator: { id: `user-rguide-${category.toLowerCase()}`, name: `R ${category}`, avatar: avatar(category) },
    upvotes: 0,
    createdAt,
    stops,
    sources: listSources(overviewSources, stops),
  };
}

